-- beijing-poly-art-cultural-cooperation (source: docs/support docs/V2/新闻提炼(1).docx)
insert into public.news (slug, category_id, title_zh, title_en, summary_zh, summary_en, body_zh, body_en, tags, cover_image_path, status, published_at, is_featured, author_name, source_url)
values (
  'beijing-poly-art-cultural-cooperation',
  (select id from public.news_categories where slug = 'association-news'),
  $obci$大洋洲工商业委员会与保利艺术教育共商中澳人文艺术合作 拟共同策划2026年悉尼春节联欢晚会$obci$, $obci$Oceania Business Council and Poly Art Education Discuss China-Australia Cultural and Arts Cooperation, Plan to Jointly Organise 2026 Sydney Spring Festival Gala$obci$,
  $obci$2025年12月11日，大洋洲工商业委员会执行会长孙国照在北京保利艺术博物馆与保利艺术教育投资有限公司总经理陈鹏、副总经理解瑞会谈，双方就共同策划2026年澳大利亚悉尼春节联欢晚会达成共识，并计划在墨尔本拓展艺术展览、教育研学及青少年交流合作。$obci$, $obci$On 11 December 2025, Oceania Business Council Executive President Sunny Sun met Poly Art Education Investment Co., Ltd. General Manager Chen Peng and Deputy General Manager Xie Rui at the Poly Art Museum in Beijing. The two sides agreed to jointly plan the 2026 Sydney Spring Festival Gala and to expand arts, education and youth exchange cooperation in Melbourne.$obci$,
  $obci$2025年12月11日，大洋洲工商业委员会执行会长孙国照在北京保利艺术博物馆与保利艺术教育投资有限公司总经理陈鹏、副总经理解瑞举行会谈。

双方围绕深化中澳人文艺术合作展开深入交流，并达成多项共识。核心议题是共同策划打造2026年澳大利亚悉尼春节联欢晚会，旨在将其发展为促进中澳文化互鉴的高水平品牌活动。此外，双方计划未来在墨尔本拓展艺术展览、教育研学及青少年交流等多形式合作，构建常态化文化交流网络。

此次会晤标志着双方在人文艺术领域的务实合作迈出关键一步，为未来系列文化项目的推进奠定了坚实基础。$obci$,
  $obci$On 11 December 2025, Oceania Business Council Executive President Sunny Sun held talks at the Poly Art Museum in Beijing with Chen Peng, General Manager, and Xie Rui, Deputy General Manager, of Poly Art Education Investment Co., Ltd.

The two sides held in-depth discussions on deepening China-Australia cultural and arts cooperation and reached consensus on a number of points. The central topic was jointly planning and staging the 2026 Spring Festival Gala in Sydney, Australia, with the aim of developing it into a high-level flagship event that promotes mutual cultural exchange between China and Australia. In addition, the two sides plan to expand cooperation in Melbourne in the future across a range of formats, including art exhibitions, educational study tours and youth exchanges, building a regular network for cultural exchange.

The meeting marked a key step forward in the two sides' practical cooperation in the cultural and arts field and laid a solid foundation for advancing a series of cultural projects in the future.$obci$,
  array['culture-arts']::text[], null, 'published', '2025-12-11T10:00:00+11:00'::timestamptz, false, null, null
)
