-- lishui-pharma-conference-ccpit-agreement (source: docs/support docs/V2/新闻提炼(1).docx)
insert into public.news (slug, category_id, title_zh, title_en, summary_zh, summary_en, body_zh, body_en, tags, cover_image_path, status, published_at, is_featured, author_name, source_url)
values (
  'lishui-pharma-conference-ccpit-agreement',
  (select id from public.news_categories where slug = 'association-news'),
  $obci$大洋洲工商业委员会率团参加第十九届成长型医药企业发展大会 与丽水市贸促会签署战略合作协议$obci$, $obci$Oceania Business Council Leads Delegation to the 19th Growth-Stage Pharmaceutical Enterprises Development Conference and Signs Strategic Cooperation Agreement with Lishui CCPIT$obci$,
  $obci$2025年11月23日，第十九届成长型医药企业发展大会在浙江丽水开幕，大洋洲工商业委员会会长孙国照率团参会并展示马努卡蜂蜜等健康产品。会议期间，委员会与丽水市贸促会签署战略合作协议，达成邀请丽水医药企业参加2026年墨尔本澳中健康产业博览会、在青田进口商品城设立大洋洲馆、考察丽水本地医药企业三项合作。$obci$, $obci$On 23 November 2025 the Oceania Business Council, led by President Sunny Sun, attended the 19th Growth-Stage Pharmaceutical Enterprises Development Conference in Lishui, Zhejiang, and signed a strategic cooperation agreement with Lishui CCPIT covering the 2026 Australia-China Health Industry Expo in Melbourne, an Oceania pavilion in Qingtian and visits to local pharmaceutical enterprises.$obci$,
  $obci$2025年11月23日，第十九届成长型医药企业发展大会在浙江丽水开幕。澳大利亚大洋洲工商业委员会会长孙国照率团参会，展示马努卡蜂蜜等健康产品，并与丽水市政府开展交流。

会议期间，委员会与丽水市贸促会签署战略合作协议，建立长期合作关系。双方达成三项合作：一是邀请丽水医药企业组团参加2026年10月在墨尔本举办的澳中健康产业博览会，丽水市将提供出海补助；二是推动在青田进口商品城设立大洋洲馆，引进澳大利亚产品；三是代表团实地考察丽水本地医药企业，促进产业对接。

此次合作为两地医药健康产业搭建了双向贸易与交流平台。$obci$,
  $obci$On 23 November 2025, the 19th Growth-Stage Pharmaceutical Enterprises Development Conference opened in Lishui, Zhejiang. Sunny Sun, President of the Oceania Business Council of Australia, led a delegation to the conference, showcased health products such as manuka honey, and held exchanges with the Lishui Municipal Government.

During the conference, the Council signed a strategic cooperation agreement with the Lishui Council for the Promotion of International Trade (CCPIT), establishing a long-term cooperative relationship. The two sides agreed on three areas of cooperation: first, inviting Lishui pharmaceutical enterprises to attend as a group the Australia-China Health Industry Expo to be held in Melbourne in October 2026, with Lishui providing subsidies for going overseas; second, promoting the establishment of an Oceania Pavilion at the Qingtian Imported Commodities City to bring in Australian products; and third, arranging for the delegation to visit local pharmaceutical enterprises in Lishui on site to promote industry matchmaking.

This cooperation has built a platform for two-way trade and exchange between the pharmaceutical and health industries of the two regions.$obci$,
  array['health']::text[], null, 'published', '2025-11-23T12:00:00+11:00'::timestamptz, false, null, null
)
